package com.example.starter.incident;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MissingRequestHeaderException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 统一错误响应：业务异常按 ApiException 携带的状态码返回，
 * 请求体/请求头解析失败归为 400，其余未预期异常归为 500。
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    /**
     * 错误响应体：code 为机器可区分错误码，message 为人读描述；
     * details 为可选结构化明细（如解决门禁未完成项、未解除阻塞的事件键列表），无则 null。
     */
    public record ErrorBody(String code, String message, Object details) {
    }

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<ErrorBody> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.status())
                .body(new ErrorBody(ex.code(), ex.getMessage(), ex.details()));
    }

    @ExceptionHandler({HttpMessageNotReadableException.class, MissingRequestHeaderException.class})
    public ResponseEntity<ErrorBody> handleBadRequest(Exception ex) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorBody("BAD_REQUEST", "请求格式非法: " + ex.getMessage(), null));
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 处置任务实体，对应 incident_tasks 表。
 * (incidentId, taskKey) 唯一，同键同内容幂等，同键不同内容冲突；
 * 每事件至多 20 个任务。doneBy/doneAt 仅 DONE 有值，cancelledBy/cancelledAt 仅 CANCELLED 有值。
 * 时间均为 UTC。
 */
public record IncidentTask(
        long id,
        long incidentId,
        String taskKey,
        String groupCode,
        String title,
        TaskStatus status,
        String createdBy,
        String doneBy,
        Instant doneAt,
        String cancelledBy,
        Instant cancelledAt,
        Instant createdAt,
        Instant updatedAt) {

    /**
     * 判断两条任务的业务内容是否一致（用于 taskKey 幂等比对；阻塞事件集合另行比对）。
     */
    public boolean sameContent(String groupCode, String title) {
        return this.groupCode.equals(groupCode) && this.title.equals(title);
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 处置记录实体，对应 incident_actions 表。
 * occurredAt 为客户端上报的处置发生 UTC 时间；createdAt 为服务端落库 UTC 时间。
 * (incidentId, actionKey) 唯一，同键同内容幂等，同键不同内容冲突。
 */
public record IncidentAction(
        long id,
        long incidentId,
        String actionKey,
        String actionType,
        String note,
        Instant occurredAt,
        String actor,
        Instant createdAt) {

    /**
     * 判断两条记录的业务内容是否一致（用于 actionKey 幂等比对）。
     */
    public boolean sameContent(String actionType, String note, Instant occurredAt) {
        return this.actionType.equals(actionType)
                && this.note.equals(note)
                && this.occurredAt.equals(occurredAt);
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 指挥交接单实体，对应 incident_transfers 表。
 * acceptedAt 仅 ACCEPTED 状态有值，其余为 null。
 */
public record IncidentTransfer(
        long id,
        long incidentId,
        String fromCommander,
        String toCommander,
        TransferStatus status,
        Instant createdAt,
        Instant acceptedAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 状态流转历史实体，对应 incident_status_history 表。
 * fromStatus 在事件创建（首次落库）时为 null；occurredAt 为 UTC 时间。
 */
public record StatusChange(
        long id,
        long incidentId,
        IncidentStatus fromStatus,
        IncidentStatus toStatus,
        String actor,
        Instant occurredAt) {
}

