    public record SealRecordView(int seq, String recordType, String recordKey, Instant occurredAt,
                                 int recordVersion, Long taskId, Long blockerIncidentId,
                                 JsonNode payload) {
    }

    /**
     * 封存更正附录视图：oldValue/newValue 允许为 null，表达原值或更正值为空。
