 * 调用方已持有事件行锁：未提交的同刻写入会先在锁上等待，提交后在此可见，
 * 回滚则不可见——按提交顺序裁决封存边界。
 */
public boolean existsCommandAt(long incidentId, Instant cutoff) {
    Integer count = jdbc.queryForObject(
            "SELECT COUNT(*) FROM incident_actions WHERE incident_id = ? AND occurred_at = ?",
            Integer.class, incidentId, Timestamp.from(cutoff));
    return count != null && count > 0;
}

