    Map<Long, List<Long>> adjacency = new HashMap<>();
    for (IncidentTaskRepository.Edge edge : allEdges) {
        adjacency.computeIfAbsent(edge.fromIncidentId(), k -> new ArrayList<>())
                .add(edge.toIncidentId());
    }
