    if (cycle != null && cycle.stream().anyMatch(referencedNodes::contains)) {
        throw ApiException.unprocessable("SEAL_GRAPH_CYCLE",
                "封存依赖图存在环，不能封存", new CycleDetail(cycle));
    }
}

